<template>
  <div dir="rtl" class="store-operations">
    <div class="d-flex align-center flex-wrap ga-3 mb-5"><h1 class="text-h4">إدارة المتجر</h1><v-spacer /><v-btn :loading="busy" @click="refresh">تحديث</v-btn><v-btn to="/store" variant="outlined">عرض المتجر</v-btn></div>
    <v-alert v-if="error" type="error" closable class="mb-4" @click:close="error = ''">{{ error }}</v-alert>
    <v-progress-linear v-if="busy" indeterminate class="mb-4" />
    <template v-if="boot">
      <StoreNotificationsPanel v-if="boot.permissions.orders" scope="admin"/>
      <StorePaymentsPanel v-if="tab === 'payments' && boot.permissions.finance"/>
      <v-alert v-if="boot.readiness_issues?.length && boot.permissions.settings" type="warning" variant="tonal" class="mb-4"><strong>قبل تفعيل البيع:</strong><ul><li v-for="issue in boot.readiness_issues" :key="issue">{{ issue }}</li></ul></v-alert>
      <v-tabs v-model="tab" show-arrows>
        <template v-if="boot.permissions.settings"><v-tab value="settings">الإعدادات</v-tab><v-tab value="sellers">البائعون والباقات</v-tab><v-tab value="shipping">الشحن والأسعار</v-tab></template>
        <template v-if="boot.permissions.orders"><v-tab value="orders">الطلبات</v-tab><v-tab value="returns">المرتجعات</v-tab><v-tab value="outbox">المهام</v-tab></template>
        <template v-if="boot.permissions.finance"><v-tab value="accounts">الأرصدة</v-tab><v-tab value="payouts">الصرف</v-tab><v-tab value="refunds">الاسترداد</v-tab><v-tab value="payments">مطابقة الدفع</v-tab></template>
      </v-tabs>
      <v-card class="pa-5 mt-3" v-if="tab === 'settings' && settings">
        <v-form @submit.prevent="saveSettings">
          <v-row><v-col v-for="field in switches" :key="field.key" cols="12" sm="6" md="4"><v-switch v-model="settings[field.key]" :aria-label="field.label" :label="field.label" hide-details /></v-col></v-row>
          <v-row><v-col cols="12" sm="4"><v-text-field v-model.number="settings.hold_hours" type="number" min="1" max="168" aria-label="مهلة تأكيد الطلب (ساعة)" label="مهلة تأكيد الطلب (ساعة)" /></v-col><v-col cols="12" sm="4"><v-text-field v-model.number="settings.quote_minutes" type="number" min="1" max="60" aria-label="صلاحية عرض السعر (دقيقة)" label="صلاحية عرض السعر (دقيقة)" /></v-col><v-col cols="12" sm="4"><v-text-field v-model.number="settings.max_unconfirmed_orders_per_customer" type="number" min="1" aria-label="أقصى طلبات غير مؤكدة للعميل" label="أقصى طلبات غير مؤكدة للعميل" /></v-col></v-row>
          <v-row><v-col cols="12" md="6"><v-select v-model="settings.platform_shipping_account_id" :items="shipping.filter(a => a.company_id === boot.platform_company_id)" item-title="name" item-value="id" clearable aria-label="حساب شحن المنصة البديل" label="حساب شحن المنصة البديل" /></v-col><v-col cols="12" md="6"><v-select v-model="settings.legal_document_ids" :items="boot.legal_documents" item-title="key" item-value="id" multiple chips aria-label="وثائق الشراء والخصوصية والمرتجعات المنشورة" label="وثائق الشراء والخصوصية والمرتجعات المنشورة" /></v-col></v-row>
          <v-row><v-col cols="12" sm="6"><v-select v-model="settings.tax_mode" :items="[{title:'لم يضبط',value:'unconfigured'},{title:'حسب حالة كل بائع (الموصى به)',value:'per_seller'},{title:'لا ضريبة وفق الإعداد المعتمد',value:'none'},{title:'الأسعار تشمل الضريبة',value:'included'},{title:'تضاف الضريبة',value:'exclusive'}]" aria-label="أسلوب الضريبة" label="أسلوب الضريبة" /></v-col><v-col cols="12" sm="6"><v-text-field v-if="['included','exclusive'].includes(settings.tax_mode)" v-model.number="settings.default_tax_rate_bps" type="number" min="0" max="10000" aria-label="معدل الضريبة بنقاط الأساس (100 = 1%)" label="معدل الضريبة بنقاط الأساس (100 = 1%)" /></v-col></v-row>
          <v-alert type="info" variant="tonal" class="mb-4">الدفع عند الاستلام متاح دائمًا. يظهر الدفع بالبطاقة بجانبه عند تفعيل الدفع الإلكتروني ووجود بوابة مكتملة وجاهزة؛ غيابها لا يمنع البيع.</v-alert><h2 class="text-h6 mb-3">سياسة المرتجعات الافتراضية</h2><p>الحقوق الإلزامية لا تتوقف على تحصيل الناقل، ولا يتحمل العميل نفقات الإرجاع القانوني. تسجل الاستثناءات القانونية لكل منتج.</p><v-text-field v-model.number="settings.return_policy.change_of_mind_days" type="number" min="14" max="365" label="مهلة تغيير الرأي بالأيام" aria-label="مهلة تغيير الرأي بالأيام" /><v-text-field v-model.number="settings.return_policy.defect_days" type="number" min="30" max="365" label="مهلة العيب بالأيام" aria-label="مهلة العيب بالأيام" />
          <h2 class="text-h6 mb-3">سياسة البائع الافتراضية</h2><StorePolicyFields v-model="settings.seller_policy" />
          <v-alert type="info" variant="tonal" class="mb-3">الصرف التلقائي ينشئ طلب تحويل للمراجعة. لا يسجل النظام تحويلًا بنكيًا إلا بعد توثيق تنفيذه فعليًا. حساب الدفع الإلكتروني يضبط من شاشة بوابات الدفع.</v-alert>
          <v-btn to="/app/payment-gateways" variant="outlined" class="me-3">بوابات الدفع</v-btn><v-btn type="submit" color="primary" :loading="busy">حفظ الإعدادات</v-btn>
        </v-form>
      </v-card>
      <v-card v-if="tab === 'sellers'" class="pa-5"><v-select v-model="companyId" :items="boot.companies" item-title="name" item-value="id" aria-label="الشركة البائعة" label="الشركة البائعة" @update:model-value="loadSeller" />
        <v-form v-if="seller" @submit.prevent="saveSeller"><v-alert v-if="seller.profile.policy_review_required" type="warning" class="mb-4">تغيرت الباقة. راجع الاستثناءات ثم احفظ لاعتمادها قبل قبول طلبات جديدة.</v-alert>
          <v-switch v-model="seller.profile.is_enabled" aria-label="تفعيل البائع في المتجر" label="تفعيل البائع في المتجر" /><v-select v-model="seller.profile.warehouse_id" :items="seller.warehouses" item-title="name" item-value="id" aria-label="مخزن تنفيذ طلبات المتجر" label="مخزن تنفيذ طلبات المتجر" /><v-select v-model="seller.profile.shipping_account_id" :items="shipping.filter(a => [companyId, boot.platform_company_id].includes(a.company_id))" item-title="name" item-value="id" clearable aria-label="حساب الشحن (البديل حساب المنصة)" label="حساب الشحن (البديل حساب المنصة)" />
          <h2 class="text-h6">عنوان استلام الشحنة من البائع</h2><v-row><v-col v-for="field in addressFields" :key="field.key" cols="12" sm="6"><v-text-field v-model="seller.profile.pickup_address[field.key]" :aria-label="field.label" :label="field.label" :required="field.required" /></v-col><v-col cols="12" sm="6"><v-select v-model="seller.profile.pickup_address.governorate_code" :items="boot.governorates" item-title="name" item-value="id" aria-label="المحافظة" label="المحافظة" /></v-col></v-row>
          <h2 class="text-h6 mt-5">صفة البائع ومستنداته</h2><p>يمكن تسجيل بائع فردي أو نشاط غير مسجل دون اشتراط سجل تجاري أو بطاقة ضريبية. هذه بيانات تشغيلية معلنة، ولا تمثل ترخيصًا أو تحققًا حكوميًا.</p>
          <v-select v-model="seller.profile.business_profile.seller_kind" :items="[{title:'بائع فردي',value:'individual'},{title:'نشاط غير مسجل رسميًا',value:'unregistered_business'},{title:'منشأة مسجلة رسميًا',value:'registered_business'}]" label="صفة البائع" aria-label="صفة البائع" />
          <v-select v-model="seller.profile.business_profile.document_status" :items="[{title:'بيانات معلنة دون مستندات رسمية',value:'self_declared'},{title:'مستندات راجعتها الإدارة',value:'documents_reviewed'}]" label="حالة مستندات البائع" aria-label="حالة مستندات البائع" />
          <v-text-field v-if="seller.profile.business_profile.document_status==='documents_reviewed'" v-model="seller.profile.business_profile.reference" label="مرجع مراجعة المستندات" />
          <StoreLocalDeliverySettings :key="'delivery-'+companyId" :company-id="companyId" />
          <StoreSellerTaxFields v-model="seller.profile.tax_profile" :products="seller.products || []" /><StoreProductReturnFields :key="companyId" :products="seller.products || []" :busy="busy" @save="saveProductReturn" />
          <h2 class="text-h6 mb-4">استثناءات هذه الشركة</h2><StorePolicyFields v-model="seller.profile.policy_overrides" inherit /><v-expansion-panels class="mb-4"><v-expansion-panel title="السياسة الفعلية الموروثة"><v-expansion-panel-text><dl><template v-for="(value, key) in seller.effective_policy" :key="key"><dt>{{ policyLabels[key] || key }}</dt><dd>{{ value }}</dd></template></dl></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
          <template v-if="boot.permissions.finance"><v-alert v-if="seller.payout_proposal" type="info" variant="tonal" class="my-3">أرسل البائع بيانات استلام مستحقاته للمراجعة: {{ seller.payout_proposal.account_holder }} — {{ seller.payout_proposal.account_number }}<v-btn variant="text" @click="bank={...seller.payout_proposal};replaceBank=true">نقل البيانات إلى نموذج الاعتماد</v-btn></v-alert><v-checkbox v-model="replaceBank" :label="seller.payout_destination_configured ? 'تغيير بيانات التحويل البنكي المعتمدة' : 'إضافة بيانات التحويل البنكي المعتمدة'" /><v-row v-if="replaceBank"><v-col v-for="field in bankFields" :key="field.key" cols="12" sm="6"><v-text-field v-model="bank[field.key]" :aria-label="field.label" :label="field.label" autocomplete="off" /></v-col></v-row></template>
          <v-btn type="submit" color="primary" :loading="busy">حفظ البائع واعتماد الاستثناءات</v-btn>
        </v-form>
      </v-card>
      <v-card v-if="tab === 'shipping'" class="pa-5">
        <v-btn @click="newShipping">إضافة حساب شحن</v-btn><v-table class="mt-3"><thead><tr><th>الشركة</th><th>حساب الشحن</th><th>التحصيل</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="account in shipping" :key="account.id"><td>{{ companyName(account.company_id) }}</td><td>{{ account.name }}</td><td>{{ account.cod_beneficiary === 'seller' ? 'البائع' : 'المنصة' }}</td><td>{{ account.is_active ? 'مفعل' : 'معطل' }}</td><td><v-btn variant="text" @click="editShipping(account)">تعديل وأسعار</v-btn></td></tr></tbody></v-table>
        <v-form v-if="shippingForm" @submit.prevent="saveShipping" class="mt-5"><v-text-field v-model="shippingForm.name" aria-label="اسم الحساب" label="اسم الحساب" required /><v-select v-model="shippingForm.company_id" :items="boot.companies" item-title="name" item-value="id" aria-label="مالك التعاقد" label="مالك التعاقد" :disabled="!!shippingForm.id" /><v-select v-model="shippingForm.driver" :items="shippingDrivers" item-title="name" item-value="id" aria-label="موصل الشحن" label="موصل الشحن" :disabled="!!shippingForm.id" /><v-select v-model="shippingForm.cod_beneficiary" :items="[{title:'تحويل التحصيل للبائع',value:'seller'},{title:'تحويل التحصيل للمنصة',value:'platform'}]" aria-label="جهة توريد COD المتعاقد عليها" label="جهة توريد COD المتعاقد عليها" /><v-switch v-model="shippingForm.is_active" aria-label="مفعل" label="مفعل" /><v-switch v-model="shippingForm.is_test_mode" aria-label="حساب اختبار" label="حساب اختبار" /><v-text-field v-for="(kind, key) in shippingDriverFields" :key="key" v-model="shippingForm.credentials[key]" :label="key + ' (اترك فارغًا للاحتفاظ بالمحفوظ)'" :type="kind === 'secret' ? 'password' : 'text'" autocomplete="new-password" /><v-btn type="submit" color="primary" :loading="busy">حفظ حساب الشحن</v-btn></v-form>
        <v-form v-if="shippingForm?.id" @submit.prevent="saveRate" class="mt-6"><h2 class="text-h6 mb-3">تسعير المحافظة لكل شحنة بائع</h2><v-select v-model="rate.scope_company_id" :items="[{id:0,name:'السعر العام'},...companies.filter(company=>shippingForm.company_id===boot.platform_company_id || company.id===shippingForm.company_id)]" item-title="name" item-value="id" label="السعر العام أو استثناء لبائع" aria-label="نطاق سعر الشحن" @update:model-value="selectRate"/><p class="mb-3">استثناء البائع يسبق السعر العام، بما فيه منع المسار أو الدفع عند الاستلام. السعر المقبول مع الطلب يظل ثابتًا.</p><v-select v-model="rate.governorate_code" :items="boot.governorates" item-title="name" item-value="id" aria-label="المحافظة" label="المحافظة" @update:model-value="selectRate" /><v-text-field v-model="rate.fee" type="number" min="0" step="0.01" aria-label="رسوم العميل بالجنيه" label="رسوم العميل بالجنيه" /><v-text-field v-model="rate.carrier_fee" type="number" min="0" step="0.01" label="تكلفة شركة الشحن بالجنيه (فارغ = تكلفة السعر العام للاستثناء)" aria-label="تكلفة شركة الشحن بالجنيه"/><v-select v-model="rate.subsidy_payer" :items="[{title:'البائع',value:'seller'},{title:'الإدارة',value:'platform'}]" label="من يتحمل دعم الشحن مع ناقل الإدارة؟" aria-label="جهة دعم الشحن"/><v-text-field v-model="rate.free_above" type="number" min="0" step="0.01" aria-label="شحن مجاني من قيمة (اختياري)" label="شحن مجاني من قيمة (اختياري)" /><v-checkbox v-model="rate.cod_allowed" aria-label="الدفع عند الاستلام متاح" label="الدفع عند الاستلام متاح" /><v-checkbox v-model="rate.is_active" aria-label="مسار شحن مفعل" label="مسار شحن مفعل" /><v-btn type="submit" :loading="busy">حفظ سعر المحافظة</v-btn></v-form>
      </v-card>
      <v-card v-if="tab === 'orders'" class="pa-5"><v-text-field v-model="search" aria-label="رقم الطلب" label="رقم الطلب" @keyup.enter="loadList" /><v-btn @click="loadList">بحث</v-btn><v-table><thead><tr><th>الطلب</th><th>الحالة</th><th>الدفع</th><th>الإجمالي</th><th></th></tr></thead><tbody><tr v-for="order in rows" :key="order.id"><td>{{ order.order_number }}</td><td>{{ order.status }}</td><td>{{ order.payment_status }}</td><td>{{ order.total_amount }} ج.م</td><td><v-btn variant="text" @click="openOrder(order.id)">إدارة</v-btn></td></tr></tbody></v-table></v-card>
      <v-card v-if="tab === 'accounts'" class="pa-5"><v-table><thead><tr><th>الشركة</th><th>الرصيد</th><th>معلق</th><th>مسبق</th><th>متاح للسحب</th><th></th></tr></thead><tbody><tr v-for="account in rows" :key="account.id"><td>{{ companyName(account.company_id) }}</td><td>{{ money(account.balance_minor) }}</td><td>{{ money(account.pending_minor) }}</td><td>{{ money(account.prepaid_minor) }}</td><td>{{ money(account.available_for_payout_minor) }}</td><td><v-btn @click="openLedger(account.company_id)">سجل</v-btn></td></tr></tbody></v-table><h2 class="text-h6 mt-5">تسجيل رصيد بعد استلام تحويل فعلي</h2><v-form @submit.prevent="topup"><v-select v-model="fund.company_id" :items="boot.companies" item-title="name" item-value="id" aria-label="الشركة" label="الشركة" /><v-select v-model="fund.purpose" :items="[{title:'رصيد مسبق للعمولات',value:'topup'},{title:'سداد مديونية فعلية',value:'debt'}]" label="غرض التحويل" aria-label="غرض التحويل"/><v-text-field v-model="fund.amount" type="number" min="0.01" step="0.01" aria-label="المبلغ بالجنيه" label="المبلغ بالجنيه" /><v-text-field v-model="fund.reference" aria-label="مرجع التحويل الفعلي" label="مرجع التحويل الفعلي" /><v-checkbox v-model="fund.confirmed" aria-label="تحققت من استلام المبلغ فعليًا" label="تحققت من استلام المبلغ فعليًا" /><v-btn type="submit" :disabled="!fund.confirmed" :loading="busy">تسجيل التحويل</v-btn></v-form><v-table v-if="ledger.length" class="mt-4"><thead><tr><th>التاريخ</th><th>النوع</th><th>الحساب</th><th>الحركة</th></tr></thead><tbody><tr v-for="entry in ledger" :key="entry.id"><td>{{ entry.created_at }}</td><td>{{ entry.kind }}</td><td>{{ entry.bucket }}</td><td>{{ money(entry.amount_minor) }}</td></tr></tbody></v-table></v-card>
      <v-card v-if="tab === 'payouts'" class="pa-5"><v-alert type="info" variant="tonal">المبالغ المعلقة والرصيد المسبق وحد الائتمان ليست أموالًا قابلة للسحب. يجب توثيق التحويل الفعلي قبل وضع «مدفوع».</v-alert><v-form @submit.prevent="requestPayout" class="mt-4"><v-select v-model="payoutForm.company_id" :items="boot.companies" item-title="name" item-value="id" aria-label="الشركة" label="الشركة" /><v-text-field v-model="payoutForm.amount" type="number" min="0.01" step="0.01" aria-label="طلب سحب بالجنيه" label="طلب سحب بالجنيه" /><v-btn type="submit" :loading="busy">إنشاء طلب سحب</v-btn></v-form><v-table class="mt-4"><thead><tr><th>رقم</th><th>الشركة</th><th>المبلغ</th><th>الحالة</th><th></th></tr></thead><tbody><tr v-for="payout in rows" :key="payout.id"><td>{{ payout.id }}</td><td>{{ companyName(payout.company_id) }}</td><td>{{ money(payout.amount_minor) }}</td><td>{{ payout.status }}</td><td><v-btn @click="openPayout(payout.id)">مراجعة</v-btn></td></tr></tbody></v-table></v-card>
      <v-card v-if="tab === 'returns' || tab === 'refunds'" class="pa-5"><v-table><thead><tr><th>رقم</th><th>الحالة</th><th>القيمة</th><th>السبب</th><th></th></tr></thead><tbody><tr v-for="entry in rows" :key="entry.id"><td>{{ entry.id }}</td><td>{{ entry.status }}</td><td>{{ money(entry.refund_minor ?? entry.amount_minor) }}</td><td>{{ entry.reason }}</td><td><v-btn @click="openReview(entry)">مراجعة</v-btn></td></tr></tbody></v-table></v-card>
      <v-card v-if="tab === 'outbox'" class="pa-5"><v-table><thead><tr><th>المهمة</th><th>الحالة</th><th>المحاولات</th><th>الخطأ</th><th></th></tr></thead><tbody><tr v-for="entry in rows" :key="entry.id"><td>{{ taskNames[entry.kind] || entry.kind }}</td><td>{{ entry.status }}</td><td>{{ entry.attempts }}</td><td>{{ entry.last_error }}</td><td><v-btn :disabled="busy" @click="retry(entry.id)">إعادة المحاولة</v-btn></td></tr></tbody></v-table></v-card>
      <div v-if="totalPages > 1" class="my-4"><v-pagination v-model="page" :length="totalPages" :total-visible="5" @update:model-value="loadList" /></div>
    </template>
    <v-dialog v-model="orderDialog" max-width="1000" scrollable><v-card v-if="detail"><v-card-title>{{ detail.order.order_number }}</v-card-title><v-card-text><p>الحالة: {{ detail.order.status }} — الدفع: {{ detail.order.payment_status }}</p><p>{{ detail.order.shipping_address?.recipient_name }} — {{ detail.order.shipping_address?.city }} — {{ detail.order.shipping_address?.street }}</p><v-btn v-if="detail.order.status === 'pending'" @click="confirmOrder">تأكيد الطلب (بعد التأكيد الهاتفي للدفع عند الاستلام)</v-btn>
      <v-card v-for="sub in detail.order.sub_orders" :key="sub.id" variant="outlined" class="pa-4 my-4"><h3>{{ sub.delivery_method === 'seller_local' ? 'توصيل البائع — ' : '' }}{{ sub.company_name || companyName(sub.company_id) }} — {{ sub.status }}</h3><StorePickupOverride :order="sub" admin @changed="openOrder(detail.order.id)" /><StoreLocalDeliveryActions :order="{...sub,order:detail.order}" admin @changed="openOrder(detail.order.id)" /><p v-for="item in sub.items" :key="item.id">{{ item.product?.name }} × {{ item.quantity }}</p><v-text-field v-model="tracking[sub.id]" aria-label="رقم التتبع الفعلي" label="رقم التتبع الفعلي" /><v-btn v-if="sub.delivery_method !== 'seller_local' && shipment(sub.id) && sub.status === 'processing'" @click="dispatch(sub)">تسجيل تسليم الشحنة للمندوب</v-btn><v-btn v-if="sub.status === 'confirmed'" @click="transition(sub, 'processing')">تأكيد تجهيز البائع</v-btn><v-checkbox v-if="sub.status === 'shipped' && sub.delivery_method !== 'seller_local' && detail.order.payment_method === 'cod'" v-model="collected[sub.id]" aria-label="تحقق تحصيل المبلغ من العميل" label="تحقق تحصيل المبلغ من العميل" /><v-btn v-if="sub.status === 'shipped' && sub.delivery_method !== 'seller_local'" @click="transition(sub, 'delivered')">تأكيد التسليم للعميل</v-btn><v-btn v-if="['pending','confirmed','processing'].includes(sub.status)" color="error" variant="text" @click="cancelSub(sub)">إلغاء جزء البائع</v-btn><template v-if="sub.status === 'delivered' && detail.order.payment_method === 'cod' && !sub.financial?.collected_at && boot.permissions.finance"><v-text-field v-model="collectionReferences[sub.id]" label="مرجع إثبات تحصيل العميل" aria-label="مرجع إثبات تحصيل العميل" /><v-checkbox v-model="collectionConfirmed[sub.id]" label="تحققت من تحصيل كامل مبلغ العميل" aria-label="تحققت من تحصيل كامل مبلغ العميل" /><v-btn :disabled="!collectionConfirmed[sub.id] || !collectionReferences[sub.id]" @click="collectCod(sub)">توثيق تحصيل العميل بعد التسليم</v-btn></template><v-text-field v-if="sub.status === 'delivered' && sub.delivery_method !== 'seller_local' && boot.permissions.finance" v-model="references[sub.id]" aria-label="مرجع توريد شركة الشحن" label="مرجع توريد شركة الشحن" /><v-btn v-if="sub.status === 'delivered' && sub.delivery_method !== 'seller_local' && boot.permissions.finance" @click="remit(sub)">توثيق توريد التحصيل</v-btn><v-btn v-if="sub.status === 'shipped' && sub.delivery_method !== 'seller_local' && boot.permissions.finance" color="warning" variant="outlined" @click="openRto(sub)">استلام رجوع دون تسليم</v-btn></v-card>
      <h3>سجل الطلب</h3><p v-for="event in detail.events" :key="event.id">{{ event.created_at }} — {{ event.type }}</p></v-card-text><v-card-actions><v-btn @click="orderDialog = false">إغلاق</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="rtoDialog" max-width="660"><v-card title="استلام شحنة لم تسلم للعميل"><v-card-text><v-alert type="warning" variant="tonal">استخدم هذا المسار بعد رجوع الشحنة فعليًا وفحصها. يُلغى الجزء ويسترد الدفع الإلكتروني؛ لا يُنشأ استرداد صوري للدفع عند الاستلام.</v-alert><p class="my-3">جهة التكلفة حسب سياسة الطلب: {{ rtoTarget?.financial?.rto_fee_payer === 'seller' ? 'البائع' : 'الإدارة' }}</p><v-select v-model="rtoForm.condition" :items="[{title:'صالح للإتاحة',value:'saleable'},{title:'تالف — لا يعاد للمخزون المتاح',value:'damaged'}]" label="نتيجة الفحص" aria-label="نتيجة فحص رجوع الشحنة"/><v-select v-model="rtoForm.reason" :items="[{title:'رفض العميل',value:'customer_refused'},{title:'تعذر الوصول للعميل',value:'unreachable'},{title:'تعذر شركة الشحن',value:'courier_failed'},{title:'خطأ البائع',value:'seller_error'},{title:'سبب آخر',value:'other'}]" label="سبب عدم التسليم" aria-label="سبب عدم تسليم الشحنة"/><v-text-field v-model="rtoForm.carrier_reference" label="مرجع الناقل وإثبات الاستلام" aria-label="مرجع رجوع الشحنة"/><v-text-field v-model="rtoForm.carrier_cost" type="number" min="0" step="0.01" label="إجمالي تكلفة الذهاب والعودة الفعلية بالجنيه" aria-label="تكلفة رجوع الشحنة"/><v-checkbox v-model="rtoForm.confirmed" label="أكدت الاستلام والفحص وتكلفة الناقل الفعلية" aria-label="تأكيد استلام رجوع الشحنة"/><v-alert v-if="error" type="error">{{ error }}</v-alert></v-card-text><v-card-actions><v-btn @click="rtoDialog = false">تراجع</v-btn><v-btn color="primary" :loading="busy" :disabled="!rtoForm.confirmed || !rtoForm.carrier_reference" @click="receiveRto">تسجيل الرجوع</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="reviewDialog" max-width="650"><v-card><v-card-title>مراجعة العملية #{{ review?.id }}</v-card-title><v-card-text><template v-if="reviewType === 'payout'"><p>الشركة: {{ companyName(review?.company_id) }} — {{ money(review?.amount_minor) }}</p><dl><template v-for="(value,key) in destination" :key="key"><dt>{{ bankFields.find(f => f.key === key)?.label || key }}</dt><dd>{{ value }}</dd></template></dl><v-select v-model="reviewAction" :items="payoutActions" aria-label="الإجراء" label="الإجراء" /></template><template v-else-if="reviewType === 'return'"><v-select v-model="reviewAction" :items="[{title:'اعتماد الاستلام العكسي',value:'approve'},{title:'رفض مع ذكر السبب',value:'reject'},{title:'استلام وفحص المرتجع',value:'receive'}]" aria-label="الإجراء" label="الإجراء" /><v-select v-model="returnCondition" :items="[{title:'صالح لإعادة البيع',value:'saleable'},{title:'تالف أو معيب (لا يضاف للمخزون المتاح)',value:'damaged'}]" aria-label="حالة المنتج بعد الفحص" label="حالة المنتج بعد الفحص" /></template><template v-else><v-alert type="warning">لا تؤكد الاسترداد إلا بعد مطابقته بكشف البوابة أو إثبات التحويل للعميل. إعادة الطلب للشبكة لا تعني نجاحه.</v-alert><v-select v-model="reviewAction" :items="[{title:'الاستعلام أو إعادة محاولة آمنة',value:'retry'},{title:'تأكيد استرداد موثق',value:'confirm'}]" aria-label="الإجراء" label="الإجراء" /></template><v-select v-if="reviewType === 'refund' && reviewAction === 'confirm'" v-model="reviewPayer" :items="[{title:'تحويل فعلي من المنصة للعميل',value:'platform'},{title:'تحويل البائع للعميل (تحصيل COD للبائع)',value:'seller'},{title:'استرداد بوابة مؤكد بالاستعلام',value:'gateway'}]" aria-label="جهة تنفيذ الاسترداد" label="جهة تنفيذ الاسترداد" /><v-text-field v-model="reviewReference" aria-label="مرجع التحويل أو الاسترداد الفعلي" label="مرجع التحويل أو الاسترداد الفعلي" /><v-textarea v-model="reviewReason" aria-label="سبب الرفض أو ملاحظات الفحص" label="سبب الرفض أو ملاحظات الفحص" /><v-checkbox v-model="reviewConfirmed" aria-label="راجعت البيانات وأؤكد الإجراء المختار" label="راجعت البيانات وأؤكد الإجراء المختار" /></v-card-text><v-card-actions><v-btn @click="reviewDialog = false">إلغاء</v-btn><v-btn color="primary" :disabled="!reviewConfirmed || busy" @click="applyReview">تنفيذ الإجراء</v-btn></v-card-actions></v-card></v-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import api from '@/modules/store/api/storeClient'
import StoreNotificationsPanel from '@/modules/store/components/StoreNotificationsPanel.vue'
import StorePaymentsPanel from '@/modules/store/components/StorePaymentsPanel.vue'
import StorePickupOverride from '@/modules/store/components/StorePickupOverride.vue'
import StoreLocalDeliveryActions from '@/modules/store/components/StoreLocalDeliveryActions.vue'
import StoreLocalDeliverySettings from '@/modules/store/components/StoreLocalDeliverySettings.vue'
import StoreSellerTaxFields from '@/modules/store/components/StoreSellerTaxFields.vue'
import StoreProductReturnFields from '@/modules/store/components/StoreProductReturnFields.vue'
import StorePolicyFields from '@/modules/store/components/StorePolicyFields.vue'
import { storePayload } from '@/modules/store/utils/checkoutSession'
const boot=ref(null), settings=ref(null), shipping=ref([]), shippingDrivers=ref([]), tab=ref('settings'), busy=ref(false), error=ref(''), companyId=ref(null), seller=ref(null), replaceBank=ref(false), bank=ref({}), shippingForm=ref(null), rates=ref([]), rows=ref([]), page=ref(1), totalPages=ref(1), search=ref(''), ledger=ref([])
const rate=ref({scope_company_id:0,governorate_code:null,fee:'',carrier_fee:null,subsidy_payer:'seller',free_above:null,cod_allowed:true,is_active:true}), fund=ref({company_id:null,purpose:'topup',amount:'',reference:'',confirmed:false,operation_key:crypto.randomUUID()}), payoutForm=ref({company_id:null,amount:'',operation_key:crypto.randomUUID()})
const rtoDialog=ref(false),rtoTarget=ref(null),rtoForm=ref({})
const collectionReferences=ref({}),collectionConfirmed=ref({})
const reviewPayer=ref('platform')
const orderDialog=ref(false), detail=ref(null), tracking=ref({}), collected=ref({}), references=ref({}),netReceived=ref({}),withheld=ref({}),varianceReasons=ref({}), reviewDialog=ref(false), review=ref(null), destination=ref({}), reviewType=ref(''), reviewAction=ref(''), reviewReference=ref(''), reviewReason=ref(''), reviewConfirmed=ref(false), returnCondition=ref('damaged')
const switches=[{key:'enabled',label:'فتح المتجر لقبول الطلبات'},{key:'online_enabled',label:'الدفع الإلكتروني'},{key:'allow_guest_checkout',label:'السماح بالشراء كضيف (معطل افتراضيًا)'},{key:'require_verified_email',label:'اشتراط توثيق البريد للشراء'},{key:'auto_confirm_paid_orders',label:'تأكيد الطلب المدفوع آليًا'},{key:'legal_setup_confirmed',label:'راجعت بيانات المتعاقد والسياسات المعروضة'}]
const addressFields=[{key:'recipient_name',label:'اسم مسؤول التسليم',required:true},{key:'phone',label:'هاتف الاستلام',required:true},{key:'city',label:'المدينة',required:true},{key:'street',label:'الشارع والعنوان',required:true},{key:'district',label:'الحي'},{key:'building',label:'المبنى'}]
const bankFields=[{key:'bank_name',label:'البنك'},{key:'account_holder',label:'اسم صاحب الحساب'},{key:'account_number',label:'رقم الحساب'},{key:'iban',label:'IBAN'}]
const policyLabels={funding_mode:'تمويل العمولة',credit_limit_minor:'حد الائتمان بالقرش',commission_type:'نوع العمولة',commission_percent:'نسبة العمولة',commission_fixed_minor:'العمولة الثابتة بالقرش',commission_timing:'توقيت الاستحقاق',settlement_delay_days:'تأخير الإتاحة',minimum_payout_minor:'الحد الأدنى للسحب',automatic_payout:'إنشاء طلبات السحب تلقائيًا',automatic_debt_offset:'تسوية المديونية تلقائيًا',use_sales_balance_for_commission:'خصم من الإيرادات',payout_method:'وسيلة الصرف',payout_weekday:'يوم الصرف',payout_hour:'ساعة الصرف'}
const taskNames={'notification.erp_scheduled':'تذكير فاتورة ERP','notification.store_email':'قالب بريد المتجر','account.email_verification':'توثيق البريد','shipment.create':'إنشاء الشحنة','refund.process':'تنفيذ الاسترداد','invoice.create':'إنشاء الفاتورة','account.verify_email':'توثيق البريد','order.customer_notification':'إشعار العميل','order.vendor_notification':'إشعار البائع','stats.daily':'تحديث الإحصائيات'}
const payoutActions=computed(()=>review.value?.status==='requested'?[{title:'اعتماد طلب السحب',value:'approve'},{title:'رفض الطلب',value:'reject'}]:[{title:'توثيق التحويل المنفذ',value:'paid'},{title:'رفض وإلغاء الحجز',value:'reject'}])
const shippingDriverFields=computed(()=>shippingDrivers.value.find(d=>d.id===shippingForm.value?.driver)?.fields||{})
const money=n=>new Intl.NumberFormat('ar-EG',{style:'currency',currency:'EGP'}).format(Number(n||0)/100)
const companyName=id=>boot.value?.companies.find(c=>c.id===id)?.name||`#${id}`
const get=async path=>storePayload(await api.get('/admin/store/'+path))
async function run(task){if(busy.value)return;busy.value=true;error.value='';try{await task()}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join('، ')||e.response?.data?.message||'تعذر تنفيذ العملية. حاول مجددًا.'}finally{busy.value=false}}
async function refresh(){await run(async()=>{boot.value=await get('bootstrap');settings.value=JSON.parse(JSON.stringify(boot.value.settings));if(boot.value.permissions.settings){shipping.value=await get('shipping-accounts');shippingDrivers.value=await get('shipping-drivers')}else if(tab.value==='settings')tab.value=boot.value.permissions.orders?'orders':'accounts';await fetchList()})}
async function saveSettings(){await run(async()=>{boot.value=storePayload(await api.put('/admin/store/settings',{settings:settings.value}));settings.value=JSON.parse(JSON.stringify(boot.value.settings))})}
async function loadSeller(){if(!companyId.value)return;await run(async()=>{seller.value=await get('sellers/'+companyId.value);seller.value.profile.business_profile||={seller_kind:'individual',document_status:'self_declared',reference:null};seller.value.profile.tax_profile||={status:'unconfigured',mode:'none',rate_bps:0,registration_number:null,basis:'',product_rules:[]};seller.value.profile.tax_profile.product_rules||=[];seller.value.profile.pickup_address||={};seller.value.profile.policy_overrides||={};seller.value.profile.is_enabled=!!seller.value.profile.is_enabled;replaceBank.value=false;bank.value={}})}
async function saveProductReturn({productId,...form}){await run(async()=>{seller.value=storePayload(await api.put('/admin/store/sellers/'+companyId.value+'/products/'+productId+'/return-policy',form))})}
async function saveSeller(){await run(async()=>{const payload={...seller.value.profile};if(replaceBank.value)payload.payout_destination=bank.value;seller.value=storePayload(await api.put('/admin/store/sellers/'+companyId.value,payload));replaceBank.value=false;bank.value={}})}
function newShipping(){shippingForm.value={company_id:boot.value.platform_company_id,name:'',driver:'manual',cod_beneficiary:'platform',is_active:false,is_test_mode:false,credentials:{},configuration:{}};rates.value=[];rate.value.scope_company_id=0;selectRate()}
async function editShipping(account){await run(async()=>{shippingForm.value={...account,credentials:{}};rates.value=await get(`shipping-accounts/${account.id}/rates`);rate.value.scope_company_id=0;selectRate()})}
async function saveShipping(){await run(async()=>{const form=shippingForm.value;shipping.value=storePayload(await api[form.id?'put':'post']('/admin/store/shipping-accounts'+(form.id?'/'+form.id:''),form));if(!form.id)shippingForm.value=null})}
function selectRate(){const found=rates.value.find(r=>r.governorate_code===rate.value.governorate_code && Number(r.scope_company_id||0)===Number(rate.value.scope_company_id||0)) || (Number(rate.value.scope_company_id||0)>0?rates.value.find(r=>r.governorate_code===rate.value.governorate_code && Number(r.scope_company_id||0)===0):null);rate.value={scope_company_id:Number(rate.value.scope_company_id||0),governorate_code:rate.value.governorate_code,fee:found?(found.fee_minor/100).toFixed(2):'',carrier_fee:found?.carrier_fee_minor!=null?(found.carrier_fee_minor/100).toFixed(2):null,subsidy_payer:found?.subsidy_payer||'seller',free_above:found?.free_above_minor!=null?(found.free_above_minor/100).toFixed(2):null,cod_allowed:found?.cod_allowed??true,is_active:found?.is_active??true}}
async function saveRate(){await run(async()=>{rates.value=storePayload(await api.post(`/admin/store/shipping-accounts/${shippingForm.value.id}/rates`,{...rate.value,free_above:rate.value.free_above===''?null:rate.value.free_above}))})}
async function fetchList(){if(!['orders','accounts','payouts','outbox','returns','refunds'].includes(tab.value))return;const data=storePayload(await api.get('/admin/store/'+tab.value,{params:{page:page.value,search:search.value}}));rows.value=Array.isArray(data)?data:(data?.data||[]);totalPages.value=data?.last_page||data?.meta?.last_page||1}
async function loadList(){await run(fetchList)}
async function openOrder(id){await run(async()=>{detail.value=await get('orders/'+id);orderDialog.value=true})}
const shipment=subId=>detail.value?.shipments.find(s=>s.store_sub_order_id===subId)
async function orderAction(path,payload){await run(async()=>{const result=storePayload(await api.post('/admin/store/'+path,payload));if(result?.order)detail.value=result;await fetchList()})}
async function confirmOrder(){await orderAction(`orders/${detail.value.order.id}/confirm`,{phone_confirmed:true})}
async function transition(sub,status){await run(async()=>{detail.value=storePayload(await api.patch(`/admin/store/sub-orders/${sub.id}/status`,{status,collected:!!collected.value[sub.id]}));await fetchList()})}
async function dispatch(sub){await orderAction(`shipments/${shipment(sub.id).id}/dispatch`,{tracking_number:tracking.value[sub.id]})}
async function cancelSub(sub){await transition(sub,'cancelled')}
async function collectCod(sub){await orderAction(`sub-orders/${sub.id}/collection`,{confirmed:!!collectionConfirmed.value[sub.id],reference:collectionReferences.value[sub.id]})}
async function remit(sub){await orderAction(`sub-orders/${sub.id}/remittance`,{reference:references.value[sub.id],net_received:netReceived.value[sub.id],fee_withheld:withheld.value[sub.id]||'0.00',fee_variance_reason:varianceReasons.value[sub.id]||''})}
function openRto(sub){rtoTarget.value=sub;rtoForm.value={condition:'saleable',reason:'customer_refused',carrier_reference:'',carrier_cost:'0.00',confirmed:false};error.value='';rtoDialog.value=true}
async function receiveRto(){await run(async()=>{detail.value=storePayload(await api.post('/admin/store/sub-orders/'+rtoTarget.value.id+'/rto',rtoForm.value));rtoDialog.value=false;await fetchList()})}
async function topup(){await run(async()=>{await api.post(`/admin/store/accounts/${fund.value.company_id}/topup`,fund.value);fund.value={company_id:fund.value.company_id,purpose:'topup',amount:'',reference:'',confirmed:false,operation_key:crypto.randomUUID()};await fetchList()})}
async function openLedger(id){await run(async()=>{const data=await get(`accounts/${id}/ledger`);ledger.value=data?.data||[]})}
async function requestPayout(){await run(async()=>{await api.post('/admin/store/payouts',payoutForm.value);payoutForm.value.operation_key=crypto.randomUUID();await fetchList()})}
function resetReview(type,entry){reviewType.value=type;review.value=entry;reviewAction.value='';reviewPayer.value='platform';reviewReference.value='';reviewReason.value='';reviewConfirmed.value=false;reviewDialog.value=true}
async function openPayout(id){await run(async()=>{const data=await get('payouts/'+id);destination.value=data.destination;resetReview('payout',data.payout)})}
function openReview(entry){resetReview(tab.value==='returns'?'return':'refund',entry)}
async function applyReview(){await run(async()=>{const noun={payout:'payouts',return:'returns',refund:'refunds'}[reviewType.value];await api.post(`/admin/store/${noun}/${review.value.id}/action`,{action:reviewAction.value,payer:reviewPayer.value,reference:reviewReference.value,reason:reviewReason.value,notes:reviewReason.value,condition:returnCondition.value,confirmed:reviewConfirmed.value});reviewDialog.value=false;destination.value={};await fetchList()})}
async function retry(id){await run(async()=>{await api.post(`/admin/store/outbox/${id}/retry`);await fetchList()})}
watch(tab,()=>{page.value=1;rows.value=[];ledger.value=[];if(!busy.value)loadList()});onMounted(refresh)
</script>
<style scoped>.store-operations{max-width:1500px;margin:auto}.store-operations :deep(td){white-space:normal;min-width:95px}dl{display:grid;grid-template-columns:1fr 1fr;gap:8px}dd{overflow-wrap:anywhere}ul{padding-inline-start:22px}</style>
